using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
public class VerifyCastleUI084
{
 static string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}
 static void Capture(Transform h,Vector3 p,Vector3 target,string file,float fov){var go=new GameObject("Temporary_UI_Review_Camera");var rt=new RenderTexture(1600,1100,24);var tex=new Texture2D(1600,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{var cam=go.AddComponent<Camera>();cam.transform.position=h.TransformPoint(p);cam.transform.LookAt(h.TransformPoint(target));cam.fieldOfView=fov;cam.farClipPlane=120;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1600,1100),0,0);tex.Apply();File.WriteAllBytes("Docs/assets/examples/"+file+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
 public static string Main(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Unsaved owner edits; preserve before reload");EditorSceneManager.OpenScene("Assets/Scenes/CastleServicesWorkshop.unity",OpenSceneMode.Single);AssetDatabase.Refresh();var root=GameObject.Find("Castle_Services_Prototype").transform;var h=root.Find("03_Service_Houses/04_Professions");if(root.GetComponentsInChildren<TextMesh>(true).Length!=0)throw new Exception("TextMesh remains");int ui=root.GetComponentsInChildren<Text>(true).Count(t=>t.name=="Localized_Text");if(ui!=17)throw new Exception("UI count "+ui);foreach(Transform rug in h.Find("23_Armory_Pickup_Mats")){var size=rug.Find("Service_Rug").localScale;if(Mathf.Abs(size.x-1.15f)>.001f||Mathf.Abs(size.z-1.05f)>.001f)throw new Exception("Rug size");}if(h.Find("16_Run_Interior/EditorOnly_StockPreview").gameObject.activeSelf)throw new Exception("Fixed preview visible");if(h.Find("24_Armory_Wall_Decor").GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("Decor collider");
 var native=new StringBuilder();foreach(var t in root.GetComponentsInChildren<Text>(true)){if(t.name=="Localized_Text")continue;native.AppendLine(Path(t.transform)+" active="+t.gameObject.activeInHierarchy+" text="+t.text.Replace("\n"," | "));if(t.name=="itemName"&&t.transform.IsChildOf(h)&&t.text!="")throw new Exception("Stale armory name");}File.WriteAllText("Temp/native-ui084.txt",native.ToString());
 // Legacy source building titles are disabled and superseded by the localized service signs.
 foreach(Transform house in root.Find("03_Service_Houses")){var source=house.Find("15_Gameplay_Source/Canvas");if(source!=null&&!source.gameObject.activeSelf)foreach(var t in source.GetComponentsInChildren<Text>(true)){t.text="";PrefabUtility.RecordPrefabInstancePropertyModifications(t);}}
 // Probe item centers using actual prefab geometry; no gameplay or physics simulation.
 var points=h.Find("15_Gameplay_Source/StorePoints").Cast<Transform>().Where(t=>t.name.StartsWith("storePoint")).ToArray();foreach(var p in points){var buy=p.GetComponentsInChildren<Transform>(true).First(t=>t.name=="buyPoint");if(buy.Find("PublicDropCenter")==null)throw new Exception("Drop marker missing");}
 Capture(h,new Vector3(0,2.45f,-2.65f),new Vector3(0,1.7f,2),"Armory_Random_UI_Interior",99);Capture(h,new Vector3(-9,7,-13),new Vector3(0,2.3f,.4f),"Armory_Localized_UI_Exterior",49);
 // Check the real UI RectTransform can fit longer English service names using best-fit.
 foreach(var t in root.GetComponentsInChildren<Text>(true).Where(t=>t.name=="Localized_Text")){var rt=t.rectTransform;if(rt.rect.width<=0||rt.rect.height<=0||!t.resizeTextForBestFit||t.raycastTarget)throw new Exception("UI sizing/raycast "+Path(t.transform));}
 foreach(string path in new[]{"Assets/Scripts/ItemStore.cs","Assets/Scripts/StorePoint.cs"}){var tree=Microsoft.CodeAnalysis.CSharp.CSharpSyntaxTree.ParseText(File.ReadAllText(path));if(tree.GetDiagnostics().Any(d=>d.Severity==Microsoft.CodeAnalysis.DiagnosticSeverity.Error))throw new Exception("Syntax "+path);}
 EditorSceneManager.MarkSceneDirty(h.gameObject.scene);EditorSceneManager.SaveScene(h.gameObject.scene);Selection.activeGameObject=h.gameObject;string report="PASS: 0 TextMesh components; 17 new World Space UI Text labels; best-fit enabled, raycasts disabled; 4 equal rugs; fixed preview hidden; 5 wall decorations without colliders; original itemName fields retained and stale armory values cleared; 4 centered drop markers; script syntax PASS; scene saved.";File.AppendAllText("Docs/assets/examples/CASTLE_UI084_VALIDATION.txt",report+"\n");return report;}
}

